FALLBACK_SEQUENCE = "NNNN"


def _get_sequence(part_id):
    seq = PART_SEQUENCES.get(part_id)
    if seq is not None:
        return seq
    try:
        from ..knowledge_base import get_part
        kb_part = get_part(part_id)
        if kb_part and kb_part.get("sequence"):
            return kb_part["sequence"]
    except Exception:
        pass
    return FALLBACK_SEQUENCE


def _resolve_sequence(part):
    seq = _get_sequence(part.get("id", "unknown"))
    if part.get("strand", "+") == "-":
        return reverse_complement(seq)
    return seq


class DNABackend(Backend):
    @property
    def name(self):
        return "DNA"

    def generate(self, cir, circuit_name="circuit"):
        parts = cir.all_parts
        lines = [f">{circuit_name} complete construct"]
        construct = ""
        for part in parts:
            construct += _resolve_sequence(part)
        lines.append(construct)
        for i, part in enumerate(parts):
            pid = part.get("id", "unknown")
            info = part.get("info", "")
            strand = part.get("strand", "+")
            seq = _resolve_sequence(part)
            strand_tag = f" [strand={strand}]" if strand == "-" else ""
            lines.append(f">{pid} | {info}{strand_tag}")
            lines.append(seq)
        return "\n".join(lines)

    def generate_fasta(self, cir, circuit_name="circuit"):
        return self.generate(cir, circuit_name)
